solution.javascript:
const express = require('express');
const app = express();
app.use(express.json());

let products = [
  { id: 1, name: 'Laptop', price: 15000, category: 'electronics', description: 'Yüksek performanslı laptop', stock: 25 },
  { id: 2, name: 'Telefon', price: 8000, category: 'electronics', description: 'Akıllı telefon', stock: 50 },
  { id: 3, name: 'Kulaklık', price: 500, category: 'electronics', description: 'Kablosuz kulaklık', stock: 100 },
  { id: 4, name: 'Kitap: Node.js', price: 120, category: 'books', description: 'Node.js öğrenme kitabı', stock: 30 },
  { id: 5, name: 'Kitap: JavaScript', price: 100, category: 'books', description: 'JavaScript rehberi', stock: 45 },
];
let nextId = 6;
const categories = ['electronics', 'books', 'clothing', 'home'];

function createError(status, title, detail, errors = []) {
  return { type: `https://api.example.com/errors/${title.toLowerCase().replace(/\s+/g, '-')}`, title, status, detail, errors };
}

function paginate(data, page, limit) {
  const total = data.length;
  const totalPages = Math.ceil(total / limit);
  const offset = (page - 1) * limit;
  return {
    data: data.slice(offset, offset + limit),
    pagination: { currentPage: page, totalPages, totalItems: total, itemsPerPage: limit, hasNextPage: page < totalPages, hasPrevPage: page > 1 },
  };
}

// Ürünleri listele
app.get('/api/v1/products', (req, res) => {
  const page = Math.max(1, parseInt(req.query.page) || 1);
  const limit = Math.min(100, Math.max(1, parseInt(req.query.limit) || 10));
  let filtered = [...products];

  if (req.query.category) filtered = filtered.filter(p => p.category === req.query.category);
  if (req.query.minPrice) filtered = filtered.filter(p => p.price >= Number(req.query.minPrice));
  if (req.query.maxPrice) filtered = filtered.filter(p => p.price <= Number(req.query.maxPrice));

  if (req.query.sort) {
    const desc = req.query.sort.startsWith('-');
    const field = desc ? req.query.sort.slice(1) : req.query.sort;
    filtered.sort((a, b) => desc ? b[field] - a[field] : a[field] - b[field]);
  }

  res.json(paginate(filtered, page, limit));
});

// Ürün detayı
app.get('/api/v1/products/:id', (req, res) => {
  const product = products.find(p => p.id === Number(req.params.id));
  if (!product) return res.status(404).json(createError(404, 'Not Found', `Ürün #${req.params.id} bulunamadı`));

  res.json({
    data: product,
    _links: {
      self: { href: `/api/v1/products/${product.id}` },
      update: { href: `/api/v1/products/${product.id}`, method: 'PUT' },
      delete: { href: `/api/v1/products/${product.id}`, method: 'DELETE' },
      category: { href: `/api/v1/categories/${product.category}/products` },
    },
  });
});

// Ürün oluştur
app.post('/api/v1/products', (req, res) => {
  const errors = [];
  if (!req.body.name) errors.push({ field: 'name', message: 'Ürün adı zorunludur' });
  if (!req.body.price || req.body.price <= 0) errors.push({ field: 'price', message: 'Fiyat pozitif bir sayı olmalıdır' });
  if (!req.body.category || !categories.includes(req.body.category)) errors.push({ field: 'category', message: 'Geçerli bir kategori seçiniz' });

  if (errors.length > 0) return res.status(400).json(createError(400, 'Validation Error', 'İstek doğrulanamadı', errors));

  const product = { id: nextId++, ...req.body, stock: req.body.stock || 0 };
  products.push(product);
  res.status(201).json({ data: product });
});

// Ürün güncelle
app.put('/api/v1/products/:id', (req, res) => {
  const index = products.findIndex(p => p.id === Number(req.params.id));
  if (index === -1) return res.status(404).json(createError(404, 'Not Found', `Ürün #${req.params.id} bulunamadı`));

  products[index] = { ...products[index], ...req.body, id: products[index].id };
  res.json({ data: products[index] });
});

// Ürün sil
app.delete('/api/v1/products/:id', (req, res) => {
  const index = products.findIndex(p => p.id === Number(req.params.id));
  if (index === -1) return res.status(404).json(createError(404, 'Not Found', `Ürün #${req.params.id} bulunamadı`));

  products.splice(index, 1);
  res.status(204).send();
});

// Kategoriler
app.get('/api/v1/categories', (req, res) => {
  res.json({ data: categories });
});

app.get('/api/v1/categories/:name/products', (req, res) => {
  const page = Math.max(1, parseInt(req.query.page) || 1);
  const limit = Math.min(100, Math.max(1, parseInt(req.query.limit) || 10));
  const filtered = products.filter(p => p.category === req.params.name);
  res.json(paginate(filtered, page, limit));
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`API: http://localhost:${PORT}`));
